<template><div class="page-screen"><header class="page-head"><div><h1 class="page-title">外链管理</h1><p class="page-subtitle">集中管理对外分享，确认访问方式与有效期。</p></div><button class="btn primary" @click="run(create)"><Icon name="plus"/>创建外链</button></header><div class="table-page-body"><div class="toolbar"><div class="filter-tabs"><button v-for="t in [['all','全部外链'],['active','有效'],['inactive','已失效']]" :key="t[0]" class="filter-tab" :class="{active:tab===t[0]}" @click="patch({tab:t[0],page:1})">{{t[1]}}</button></div><input class="input directory-search" type="search" v-model="keyword" placeholder="搜索分享文件"/></div><div class="table-shell"><div class="table-scroll"><div v-if="error" class="empty"><p>{{error}}</p><button class="btn" @click="load">重试</button></div><div v-else-if="busy" class="empty">正在加载…</div><table v-else class="links-list"><thead><tr><th><button class="link-sort" @click="patch({order:route.query.order==='desc'?'asc':'desc',page:1})">分享文件<Icon :name="route.query.order==='desc'?'down':'up'"/></button></th><th>访问方式</th><th>有效期至</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="l in paged" :key="l.id"><td><div class="file-name-cell"><FileGlyph :item="{name:l.fileName}"/><button class="file-name-button truncate" @click="run(()=>previewLink(l))"><span class="file-name">{{l.fileName||'文件已删除'}}</span><span class="file-secondary">创建于 {{time(l.createdAt)}}</span></button></div></td><td>{{l.requirePassword?'凭提取码':'持有链接'}}<p class="file-secondary">{{l.permission==='download'?'允许下载':'仅预览'}} · {{l.downloadCount}} / {{l.downloadLimit<0?'不限':l.downloadLimit}}</p></td><td>{{l.expiresAt?time(l.expiresAt):'长期有效'}}</td><td><span class="status" :class="ops.linkStatus(l)==='有效'?'good':ops.linkStatus(l)==='已过期'?'warn':'off'">{{ops.linkStatus(l)}}</span></td><td><div class="link-actions"><button v-if="ops.linkStatus(l)==='有效'" @click="run(()=>ops.copyText(l.shareUrl))">复制</button><button v-if="ops.linkStatus(l)==='有效'" @click="run(()=>revoke(l))">停用</button><button v-else @click="run(()=>hide(l))">移除记录</button><button class="icon-button" title="更多操作" @click="more($event,l)"><Icon name="more"/></button></div></td></tr><tr v-if="!filtered.length"><td colspan="5"><div class="empty"><div class="empty-symbol"><Icon name="globe"/></div><h3>没有这类外链</h3><p>选择有权分享的文件创建外链。</p></div></td></tr></tbody></table></div><Pager :total="filtered.length" :page="page" :size="size" @page="patch({page:$event})" @size="patch({size:$event,page:1})"/></div></div></div></template>
<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import * as api from '../api';import * as ops from '../operations';import {ui,run,dialog,confirm,changed} from '../state';import Icon from '../components/Icon.vue';import FileGlyph from '../components/FileGlyph.vue';import Pager from '../components/Pager.vue';import {formatTime as time} from '../../utils/formatters';
const route=useRoute(),router=useRouter(),rows=ref([]),busy=ref(false),error=ref(''),keyword=ref(route.query.keyword||'');let seq=0;
const tab=computed(()=>route.query.tab||'all'),page=computed(()=>Number(route.query.page)||1),size=computed(()=>Number(route.query.size)||ui.prefs.pageSize);
const collator=new Intl.Collator('zh-CN',{numeric:true,sensitivity:'base'});
const filtered=computed(()=>rows.value.filter(l=>(l.fileName||'').toLowerCase().includes(keyword.value.toLowerCase())&&(tab.value==='all'||(tab.value==='active')===(ops.linkStatus(l)==='有效'))).sort((a,b)=>(route.query.order==='desc'?-1:1)*collator.compare(a.fileName||'',b.fileName||'')||a.id.localeCompare(b.id)));
const paged=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value));
function patch(q){router.replace({query:{...route.query,...q}});}
async function load(){const n=++seq;busy.value=true;error.value='';try{const r=await api.get('/api/drive/me/links');if(n===seq)rows.value=r;}catch(e){if(n===seq)error.value=e.message;}finally{if(n===seq)busy.value=false;}}
async function create(){const item=await dialog({title:'选择分享文件',fields:[{key:'item',label:'文件',type:'file'}],values:{item:null},submitLabel:'下一步',onSubmit:v=>{if(!v.item?.itemId)throw new Error('请选择文件');return {id:v.item.itemId,name:v.item.name};}});if(item)await ops.linkDialog(item);}
async function previewLink(l){const list=await api.present([l.itemId]);if(!list.length)throw new Error('文件已删除或无访问权限');await ops.openItem(list[0],router);}
async function revoke(l){if(await confirm('停用外链？','停用后持有链接的用户将无法访问。')){await api.revokeLink(l.id);changed();}}
async function hide(l){if(await confirm('移除失效记录？','仅从你的列表隐藏此记录，文件和审计记录保留。')){await api.send('/api/links/'+l.id+'/record',undefined,'DELETE');changed();}}
function more(e,l){ops.menu(e,[{label:'修改设置',icon:'edit',disabled:l.revoked,run:()=>ops.linkDialog({id:l.itemId,name:l.fileName},l)},{label:'访问日志',icon:'info',run:()=>ops.linkLogs(l)}]);}
watch(keyword,v=>patch({keyword:v||undefined,page:1}));watch(()=>ui.revision,load);onMounted(load);onUnmounted(()=>seq++);
</script>
